"""Build the portable rehearsal guide from the same script used by HTML/PPT notes."""
from pathlib import Path
import json,re,html
R=Path(__file__).resolve().parents[2];P=R/'work/presentation';O=R/'outputs'
D=json.loads((P/'deck-data.json').read_text());J=json.loads((P/'presenter-script.json').read_text());S={s['id']:s for s in D['slides']};T=J['sections'];E=lambda x:html.escape(str(x),quote=True)
assert [s['slideId'] for s in T]==[s['id'] for s in D['slides'] if s['core']]
assert sum(s['minutes'] for s in T)==40
assert all(isinstance(s['talkTrack'],list) and s['talkTrack'] for s in T)
def clock(n):
 sec=round(n*60);return f'{sec//60:02}:{sec%60:02}'
def words(s):return len(re.findall(r'\S+',' '.join(s['talkTrack'])+' '+s['transition']))
spoken=sum(words(s) for s in T if s['minutes']);discussionWords=sum(words(s) for s in T if not s['minutes'])
chapters={'opening':'Opening','strategy':'Finance strategy','grounding':'Grounded agents','evals':'Evaluation','workflows':'Reliable workflows','growth':'Engineer growth','closing':'Close + discussion'}
pacing=[];elapsed=0;rows=[];nav=[];cards=[];md=[]
md+=['# AI Engineer NYC 2026 — presenter guide','', '40-minute rehearsal target + discussion · Revised October 25, 2026','',J['timingNote'],'',f'The timed script contains approximately {spoken:,} words, plus {discussionWords} words for the discussion handoff. That allows room for pauses and pointing at the walkthroughs. Rehearse aloud; the allocation is not measured delivery time.','', '## How to use this guide','', '- Open the presentation in Present mode and keep this guide on a second screen or printed. The same spoken text is embedded in PowerPoint speaker notes and the HTML Speaker notes panel.','- Speak the story, point to its decision, then state the transferable lesson. The visible analytical paragraphs are also for later reading; do not read them all aloud.','- The delivery cue is for you; it is not part of the spoken text. The transition is spoken. Preserve short qualifications when distinguishing reported results from invented teaching examples.','- If running late, drop supporting examples and use the short route below. Keep the five main walkthroughs and the final decisions.','', '## Run of show','', '| Slide | Page / story | Time | Start → end |','|---|---|---|---|']
for i,t in enumerate(T,1):
 s=S[t['slideId']];a=elapsed;elapsed+=t['minutes'];end=elapsed;duration=clock(t['minutes']) if t['minutes'] else 'Discussion';ran=f'{clock(a)}–{clock(end)}' if t['minutes'] else 'After 40:00'
 rows.append(f'<tr><td>{i:02}</td><td><a href="#s{i:02}">{E(s["title"])}</a></td><td>{duration}</td><td>{ran}</td></tr>');md.append(f'| {i:02} | {s["title"]} | {duration} | {ran} |')
 nav.append(f'<a href="#s{i:02}"><span>{i:02}</span><b>{E(s["title"])}</b><small>{ran}</small></a>')
 current=chapters[s['chapter']]
 if not pacing or pacing[-1][0]!=current:pacing.append([current,a,end])
 else:pacing[-1][2]=end
 cards.append(f'<article class="script-card" id="s{i:02}"><header><div class="eyebrow">{E(current)} · slide {i:02}</div><h2>{E(s["title"])}</h2><div class="timing">{duration} · {ran}</div></header><aside class="cue"><b>Delivery cue</b><p>{E(t["deliveryCue"])}</p></aside><div class="spoken">'+''.join('<p>'+E(p)+'</p>' for p in t['talkTrack'])+'</div><div class="transition"><b>Transition</b><p>'+E(t['transition'])+'</p></div></article>')
md+=['','## Chapter checkpoints','']+[f'- **{name}: {clock(a)} → {clock(b)}**' for name,a,b in pacing]
skip=J['shortRoute']['skip'];remaining=sum(t['minutes'] for t in T if t['slideId'] not in skip)
short=f'Target approximately 25 minutes. The retained full-route allocations total {clock(remaining)}; use the remaining time for concise bridges and pauses. Rehearse this route separately.'
skiplabels=[f'{i:02}' for i,t in enumerate(T,1) if t['slideId'] in skip]
md+=['','## Short route / running late','',short,'','Skip slides '+', '.join(skiplabels)+'. Keep slides 08, 09, 16, 18 and 23 as the main company walkthroughs, plus slide 11 as the worked cutoff example.','',J['shortRoute']['transition'],'','If only a few minutes behind, shorten the overview pages and omit secondary company examples. At the 30-minute mark, move toward the workflow recovery case and final decisions; send detailed follow-ups to the reading edition.','', '## Slide-by-slide spoken script','']
for i,t in enumerate(T,1):
 md += [f'### {i:02} — {S[t["slideId"]]["title"]}', '', f'**Allocation:** {clock(t["minutes"])}' if t['minutes'] else '**Allocation:** discussion, after the timed core', '', '**Delivery cue:** '+t['deliveryCue'],'']
 md+=t['talkTrack']+['','**Transition:** '+t['transition'],'']
md+=['## Likely discussion questions','']
qas=[]
for q in J['qa']:md += ['### '+q['question'],'',q['answer'],''];qas.append('<details open><summary>'+E(q['question'])+'</summary><p>'+E(q['answer'])+'</p></details>')
md+=['## Final rehearsal checklist','', '- Check that the opening and close fit their allocations. Practise the five main stories without reading the dense paragraphs.','- Say “precision at ten,” “mean-score points” and “synthetic example” where indicated; keep them distinct from answer accuracy, relative percentages and company outcomes.','- Check the January 20 / March 1 source cutoff explanation and the unknown-outcome branch aloud.','- Use the embedded speaker notes for the slide you are showing; use this guide for the complete timing and Q&A.','- The content, notes, links and native-slide structure have automated checks. Browser appearance, actual PowerPoint rendering and live timing still require your rehearsal.','', 'Source detail is preserved in the [presentation reading edition](ai-engineer-nyc-2026-presentation.html) and [recording supplement](ai-engineer-nyc-2026-recording-supplement.md).','']
(O/'ai-engineer-nyc-2026-presenter-guide.md').write_text('\n'.join(md))
css='''*{box-sizing:border-box}html{scroll-padding-top:85px}body{margin:0;background:#e8ebe7;color:#132f3b;font:17px/1.6 Arial,sans-serif}a{color:#075e52;text-underline-offset:3px}button{font:700 14px Arial;min-height:44px;border:1px solid #cbd4d1;background:#fffdf7;color:#132f3b;padding:10px 18px;cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #b34816;outline-offset:4px}nav{position:fixed;top:70px;bottom:0;left:0;width:280px;overflow:auto;background:#fffdf7;border-right:1px solid #cbd4d1;padding:24px 16px}nav a{display:grid;grid-template-columns:28px 1fr;gap:0 10px;font-size:12px;text-decoration:none;padding:10px 4px;border-bottom:1px solid #e7f0ea}nav b{font-weight:500}nav span{font-weight:700;color:#50616a}nav small{grid-column:2;color:#50616a}.bar{position:sticky;top:0;height:70px;background:#102e3a;color:#fffdf7;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:12px 28px;z-index:2}.bar b{font-size:16px}.actions{display:flex;gap:10px}main{margin-left:280px;max-width:1300px;padding:38px 6% 80px}.hero{background:#102e3a;color:#fffdf7;padding:44px;margin-bottom:30px}.eyebrow{text-transform:uppercase;font-size:12px;font-weight:700;letter-spacing:.08em;color:#075e52}.hero .eyebrow{color:#d5ef8c}h1{font:48px/1.1 Cambria,Georgia,serif;margin:15px 0 20px}h2{font:32px/1.16 Cambria,Georgia,serif;margin:12px 0 20px}h3{font:24px Cambria,Georgia,serif}.hero p{color:#c6d8d8}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;border-top:1px solid #50616a;margin-top:24px;padding-top:20px}.stats b{display:block;font:34px Cambria}.stats small{color:#c6d8d8}.panel,.script-card{background:#fffdf7;padding:30px 36px;margin:24px 0;border:1px solid #cbd4d1}.script-card{scroll-margin-top:90px}.script-card header{border-bottom:2px solid #075e52;padding-bottom:16px}.timing{font-weight:700;font-size:14px;color:#50616a}.cue{padding:14px 20px;background:#e7f0ea;margin:24px 0;font-size:15px;border-left:4px solid #075e52}.cue p{margin:4px 0}.cue b,.transition b{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:#075e52}.spoken{max-width:80ch}.spoken p{margin:18px 0}.transition{padding-top:18px;margin-top:24px;border-top:1px solid #cbd4d1}.transition p{font-style:italic;margin:7px 0}table{width:100%;border-collapse:collapse;font-size:14px}th{text-align:left;color:#fffdf7;background:#102e3a}td,th{padding:12px;border-bottom:1px solid #cbd4d1;vertical-align:top}td:nth-child(3),td:nth-child(4){white-space:nowrap}.table-wrap{overflow:auto}.checkpoints{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;font-size:13px}.checkpoints b{display:block;color:#075e52}.checkpoints span{font-variant-numeric:tabular-nums}details{border-top:1px solid #cbd4d1;padding:18px 0}summary{cursor:pointer;font-weight:700;min-height:35px}details p{margin:12px 0}.cues-only .spoken{display:none}.cues-only .script-card{padding-bottom:20px}.foot{font-size:13px;color:#50616a}@media(max-width:1000px){nav{display:none}main{margin:0;padding:24px}.hero{padding:30px}}@media(max-width:650px){h1{font-size:38px}.panel,.script-card{padding:24px}.bar{padding:10px 16px}.bar b{font-size:12px}.stats,.checkpoints{grid-template-columns:1fr 1fr}button{padding:8px 10px}}@media print{nav,.bar,.actions{display:none!important}main{margin:0;padding:0;max-width:none}.hero{background:white;color:#132f3b;padding:0}.hero p,.hero .eyebrow,.stats small{color:#50616a}.panel,.script-card{border:0;padding:12px 0;break-before:page}.script-card header,.cue,.transition{break-inside:avoid}.spoken p{orphans:3;widows:3}.cues-only .spoken{display:block}body{background:white;font-size:11pt}h1{font-size:30pt}h2{font-size:23pt}a{text-decoration:none}td,th{padding:6px}.stats{border-color:#cbd4d1}}'''
lead=f'<section class="hero"><div class="eyebrow">AI Engineer NYC 2026 · presenter edition</div><h1>Tell the story.<br>Explain the decision.<br>Make the lesson stick.</h1><p>A spoken companion to <em>From capability to dependable work</em>, with slide cues, transitions and discussion support.</p><div class="stats"><div><b>40 min</b><small>Rehearsal target + discussion</small></div><div><b>29 slides</b><small>Core speaking sequence</small></div><div><b>{spoken:,} words</b><small>Timed speaking text</small></div></div></section>'
intro=f'<section class="panel"><h2>Use this beside the presentation</h2><p>{E(J["timingNote"])}</p><p>Keep this guide on a second screen or print it. Speak the story and its lesson; the detailed slide paragraphs also serve people reading afterward. Delivery cues are for you. Transitions are spoken. The same script is embedded in PowerPoint speaker notes and the HTML Speaker notes panel.</p><p>Use the cue-view button to hide the full prose during rehearsal. The guide works offline; the source catalog is in the separate presentation.</p><div class="checkpoints">'+''.join(f'<div><b>{E(name)}</b><span>{clock(a)} → {clock(b)}</span></div>' for name,a,b in pacing)+'</div></section>'
run='<section class="panel"><h2>Run of show</h2><div class="table-wrap"><table><thead><tr><th>Slide</th><th>Story / page</th><th>Allocation</th><th>Start → end</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></section>'
shortHtml=f'<section class="panel"><h2>Short route / running late</h2><p>{E(short)}</p><p>Skip slides <b>{", ".join(skiplabels)}</b>. Retain the five main stories at 08, 09, 16, 18 and 23, plus the cutoff example at 11.</p><blockquote>{E(J["shortRoute"]["transition"])}</blockquote><p>If slightly behind, shorten overview pages and secondary examples. Keep the workflow recovery case and final decisions. Use the reading edition for detailed follow-ups.</p></section>'
foot='<section class="panel"><h2>Before presenting</h2><p>Rehearse aloud, especially the precision metric, source cutoff and unknown-outcome branch. The 40-minute sum is a plan, not measured delivery. Content and structure have automated checks; browser appearance and actual PowerPoint rendering still require a visual review.</p><p>Updated October 25, 2026. Reported mechanisms, historical disclosures and invented teaching examples retain distinct boundaries in the presentation sources.</p></section>'
js="document.getElementById('cue-toggle').addEventListener('click',function(){const on=document.body.classList.toggle('cues-only');this.setAttribute('aria-pressed',String(on));this.textContent=on?'Show full script':'Show cue view'});document.getElementById('print').addEventListener('click',()=>window.print());"
out='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AIE NYC 2026 · Presenter guide</title><style>'+css+'</style></head><body><header class="bar"><b>AIE NYC 2026 / PRESENTER GUIDE</b><div class="actions"><button id="cue-toggle" type="button" aria-pressed="false">Show cue view</button><button id="print" type="button">Print guide</button></div></header><nav aria-label="Slide script contents">'+''.join(nav)+'</nav><main>'+lead+intro+run+shortHtml+''.join(cards)+'<section class="panel"><h2>Likely discussion questions</h2>'+''.join(qas)+'</section>'+foot+'</main><script>'+js+'</script></body></html>'
(O/'ai-engineer-nyc-2026-presenter-guide.html').write_text(out)
print(json.dumps({'coreSections':len(T),'timedMinutes':sum(t['minutes'] for t in T),'timedWords':spoken,'discussionHandoffWords':discussionWords,'shortRouteRetainedAllocation':remaining,'qa':len(J['qa'])}))
